<div class="admin-tool-licenses" style="max-width:1180px;margin:0 auto"><style>.tool-table{width:100%;border-collapse:collapse;font-size:.78rem}.tool-table th,.tool-table td{padding:10px;text-align:left;border-bottom:1px solid #E5EFF4}.tool-table th{color:#61798A;font-size:.67rem;text-transform:uppercase}.tool-badge{display:inline-flex;padding:4px 7px;border-radius:999px;background:#EAF6FB;color:#125A96;font-size:.65rem;font-weight:800}.tool-badge.is-blocked{background:#FFF8E9;color:#9A5B00}.tool-scroll{overflow:auto}.tool-event{padding:10px 0;border-bottom:1px solid #E5EFF4;color:#456477;font-size:.76rem}</style>
